#!/usr/bin/env python3
"""Render the Rust recipe's saved palettes without generating or changing colors."""
import argparse
import json
import pathlib
import re

parser = argparse.ArgumentParser()
parser.add_argument('palettes', type=pathlib.Path)
parser.add_argument('output', type=pathlib.Path)
args = parser.parse_args()
studies = json.loads(args.palettes.read_text())
for study in studies:
    study['name'] = 'Astronaut' if pathlib.Path(study['wallpaper']).name == 'astro.jpg' else 'Osaka Jade'
font_source = pathlib.Path('docs/design/theme-study.html').read_text()
font = re.search(r'@font-face\{[^}]+\}', font_source).group(0)
html = '''<!doctype html><html><head><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>Refined wallpaper palette study</title><style>FONT
*{box-sizing:border-box}body{margin:0;color:var(--foreground,#eee);font:14px var(--font-sans,system-ui)}button{font:inherit;cursor:pointer}.controls{display:flex;gap:8px;flex-wrap:wrap;margin-bottom:18px}.mode-control{display:flex;align-items:center;gap:8px}.mode-control select{max-width:230px;border:1px solid var(--border,#555);border-radius:999px;padding:8px 12px;background:var(--secondary,#303035);color:var(--foreground,#eee);font:inherit}.controls button{background:var(--secondary,#303035);color:inherit;border:1px solid var(--border,#666);border-radius:999px;padding:8px 14px}.controls button[aria-pressed=true]{background:var(--primary,#aaa);color:var(--primary-foreground,#111)}.intro{color:var(--muted-foreground,#888);line-height:1.6;margin:0 0 16px}.study{margin:0 0 28px}h2{font-size:18px;font-weight:600;margin:0 0 12px}.wallpaper{width:100%;height:125px;object-fit:cover;border-radius:12px;margin-bottom:12px}.cards{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:12px}.mock{font-family:"VictorMono Nerd Font Mono",monospace;font-feature-settings:"ss01" 1;background:var(--background);color:var(--foreground);border-radius:16px;padding:18px;min-width:0}.mock .header{display:flex;align-items:center;justify-content:space-between;margin-bottom:18px;font-size:12px}.appearance{text-transform:uppercase;font-size:11px;letter-spacing:.08em}.dot{background:var(--primary);width:10px;height:10px;border-radius:50%}.mock h3{font-size:17px;font-weight:600;line-height:1.5;margin:0 0 5px}.muted{color:var(--foreground_muted);font-size:12px;line-height:1.6}.panel{background:var(--surface);border-radius:12px;padding:12px;margin:14px 0}.row{border-radius:8px;padding:8px;margin:3px 0;font-size:13px}.hover{background:var(--background_hover);color:var(--hover_foreground)}.selected{background:var(--background_highlight);color:var(--selection_foreground)}.focus{outline:2px solid var(--focus);outline-offset:1px}.action{border:0;background:var(--primary);color:var(--primary_foreground);padding:9px 14px;border-radius:999px;font-family:inherit;font-size:13px;margin-bottom:6px}.notice{padding:10px;border-radius:9px;margin:8px 0;font-size:14px;line-height:1.5}.notice span{display:block;font-size:12px;margin-top:3px;opacity:.9}.mini-notices{display:grid;grid-template-columns:1fr 1fr;gap:8px}.mini-notices .notice{font-size:12px;margin:0}.code{background:var(--surface_raised);padding:12px;border-radius:12px;font-size:11px;line-height:1.8;margin-top:14px;overflow:auto;white-space:pre}.swatches{display:flex;height:16px;gap:2px;margin:14px 0 9px}.swatches i{flex:1;border-radius:3px}.metrics{font-size:11px;line-height:1.8;color:var(--foreground_muted)}.only .cards{grid-template-columns:1fr}.only .mock{padding:22px}.only .mock h3{font-size:20px}[hidden]{display:none!important}@media(max-width:560px){.cards{grid-template-columns:1fr}.wallpaper{height:115px}.mock{padding:18px}}details{font-family:var(--font-sans,system-ui);font-size:12px;margin-top:12px}summary{cursor:pointer}.mapping{display:flex;align-items:center;gap:6px;margin-top:8px;font-size:11px}.mapping i{width:16px;height:16px;border-radius:4px;display:inline-block}.foot{font-size:12px;line-height:1.7;color:var(--muted-foreground,#999)}
</style></head><body><p class="intro">Wallpaper hue shapes the accents and tinted surfaces. Each mode proposes its palette; status colors fit into red, amber, green, and blue/cyan hue ranges. Light mode uses darker status text and stronger selection fills.</p><div class="controls"><label class="mode-control">Mode <select id="recipe-mode" aria-label="Theme mode"></select></label><button data-mode="both" aria-pressed="true">Both appearances</button><button data-mode="dark" aria-pressed="false">Dark</button><button data-mode="light" aria-pressed="false">Light</button></div><main></main><p class="foot">Experimental recipe v2 uses new profiles for all 23 mode names. These are actual Rust outputs; text and status pairs are checked at 4.5:1. High Contrast fits status text to 7:1. Dojo’s Derive tab now uses this recipe.</p><script>
const studies=DATA;
function lum(hex){const c=hex.slice(1).match(/../g).map(x=>parseInt(x,16)/255).map(x=>x<=.04045?x/12.92:((x+.055)/1.055)**2.4);return c[0]*.2126+c[1]*.7152+c[2]*.0722}
function contrast(a,b){const x=lum(a),y=lum(b);return(Math.max(x,y)+.05)/(Math.min(x,y)+.05)}
const root=document.querySelector('main');
const modeSelector=document.querySelector('#recipe-mode');
for(const t of studies[0].themes){const option=document.createElement('option');option.value=t.mode;option.textContent=t.mode.replaceAll('-',' ');modeSelector.append(option);}
let selectedMode='normal',selectedAppearance='both';
for(const study of studies){const section=document.createElement('section');section.className='study';const name=study.name;section.innerHTML=`<h2>${name}</h2><img class="wallpaper" src="${study.wallpaper}" alt="${name} source wallpaper"><div class="cards"></div>`;root.append(section);
 for(const theme of study.themes)for(const appearance of ['dark','light']){const p=theme[appearance],c=p.colors;const pairs=[['foreground','background'],['foreground','surface'],['foreground','surface_raised'],['foreground_muted','surface_raised'],['primary','surface_raised'],['primary_foreground','primary'],['selection_foreground','background_highlight'],['hover_foreground','background_hover'],...['error','warning','success','info'].flatMap(r=>[[r,`${r}_background`],[r,'surface_raised']])];const ratios=pairs.map(([a,b])=>contrast(c[a],c[b]));if(Math.min(...ratios)<4.5)throw Error(`${name} ${appearance} contrast failed`);if(theme.mode==='high-contrast')for(const role of ['error','warning','success','info'])for(const bg of ['background','surface','surface_raised',role+'_background'])if(contrast(c[role],c[bg])<7)throw Error('High Contrast status pair failed');
 const card=document.createElement('article');card.className='mock';card.dataset.appearance=appearance;card.dataset.mode=theme.mode;card.hidden=theme.mode!=='normal';for(const[k,v]of Object.entries(c))card.style.setProperty('--'+k,v);
 card.innerHTML=`<div class="header"><span class="appearance">${theme.mode.replaceAll('-',' ')} · ${appearance}</span><i class="dot"></i></div><h3>A quieter workspace</h3><div class="muted">An accent drawn from your wallpaper.</div><div class="panel"><div class="row">Desktop preferences</div><div class="row hover">Pointer hover</div><div class="row selected focus">✓ Selected + keyboard focus</div></div><button class="action">Apply theme</button><div class="notice" style="background:${c.warning_background};color:${c.warning}">⚠ Warning<span>Storage is almost full.</span></div><div class="notice" style="background:${c.error_background};color:${c.error}">✕ Error<span>Connection failed.</span></div><div class="mini-notices"><div class="notice" style="background:${c.success_background};color:${c.success}">✓ Saved</div><div class="notice" style="background:${c.info_background};color:${c.info}">ⓘ Update ready</div></div><div class="code"><span style="color:${c.syntax_keyword}">let</span> theme = <span style="color:${c.syntax_string}">"${name.toLowerCase()}"</span>;\n<span style="color:${c.syntax_function}">apply</span>(theme, <span style="color:${c.syntax_number}">42</span>);</div><div class="swatches">${p.terminal.map(x=>`<i style="background:${x}" title="${x}"></i>`).join('')}</div><div class="metrics">Accent ${c.primary}<br>Warning ${c.warning} · Error ${c.error}<br>Minimum checked text contrast ${Math.min(...ratios).toFixed(2)}:1</div>`;const mapping=document.createElement('details');mapping.innerHTML='<summary>Proposed palette → semantic fit</summary>'+['error','warning','success','info'].map(role=>{const range='OKLCH '+theme.feedback_ranges[role].join('–')+'°';return `<div class="mapping"><i style="background:${theme.feedback_proposals[appearance][role]}" title="Proposed ${theme.feedback_proposals[appearance][role]}"></i>→<i style="background:${c[role]}" title="Fitted ${c[role]}"></i><span>${role} · ${range}</span></div>`;}).join('');card.append(mapping);section.querySelector('.cards').append(card);}}
function update(){document.body.classList.toggle('only',selectedAppearance!=='both');for(const card of document.querySelectorAll('.mock'))card.hidden=card.dataset.mode!==selectedMode||(selectedAppearance!=='both'&&card.dataset.appearance!==selectedAppearance);for(const b of document.querySelectorAll('.controls [data-mode]'))b.setAttribute('aria-pressed',String(b.dataset.mode===selectedAppearance));}
modeSelector.onchange=()=>{selectedMode=modeSelector.value;update();};
for(const button of document.querySelectorAll('.controls [data-mode]'))button.onclick=()=>{selectedAppearance=button.dataset.mode;update();};
for(const mode of studies[0].themes.map(t=>t.mode)){modeSelector.value=mode;modeSelector.onchange();for(const appearance of ['dark','light','both']){document.querySelector(`.controls [data-mode="${appearance}"]`).click();const visible=[...document.querySelectorAll('.mock')].filter(c=>!c.hidden);if(visible.length!==(appearance==='both'?4:2)||visible.some(c=>c.dataset.mode!==mode||(appearance!=='both'&&c.dataset.appearance!==appearance)))throw Error('Mode or appearance control failed');if(document.documentElement.scrollWidth>innerWidth)throw Error('Horizontal overflow in '+mode);}}
modeSelector.value='normal';modeSelector.onchange();document.querySelector('.controls [data-mode="both"]').click();if(document.documentElement.scrollWidth>innerWidth)throw Error('Horizontal overflow');console.log('All 23 modes / 92 palettes passed rendered text contrast checks; all controls passed; no horizontal overflow');
</script></body></html>'''
html = html.replace('FONT',font).replace('DATA',json.dumps(studies))
args.output.write_text(html)
print(args.output)
